// Config plugin: release signing for the generated android/ project.
// android/ is git-ignored and regenerated by prebuild, so the signing config is injected here.
// Secrets live outside the repo in ~/.resonance/keystore.properties:
//   storeFile=/home/me/.resonance/resonance-release.keystore
//   storePassword=...
//   keyAlias=resonance
//   keyPassword=...
// If the file is missing, signing is left alone (release is debug-signed) and a warning is printed.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { withAppBuildGradle } = require('expo/config-plugins');

const PROPS_PATH = path.join(os.homedir(), '.resonance', 'keystore.properties');
const MARKER = '// resonance-release-signing';

function readProps(file) {
  const out = {};
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Za-z.]+)\s*=\s*(.*?)\s*$/);
    if (m && !line.trim().startsWith('#')) out[m[1]] = m[2];
  }
  return out;
}

const q = (v) => JSON.stringify(v).replace(/\$/g, '\\$');

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (c) => {
    if (!fs.existsSync(PROPS_PATH)) {
      console.warn(`[withReleaseSigning] ${PROPS_PATH} not found - release build will be debug-signed.`);
      return c;
    }
    const p = readProps(PROPS_PATH);
    for (const k of ['storeFile', 'storePassword', 'keyAlias', 'keyPassword']) {
      if (!p[k]) {
        console.warn(`[withReleaseSigning] "${k}" missing in ${PROPS_PATH} - release build will be debug-signed.`);
        return c;
      }
    }
    let src = c.modResults.contents;
    if (src.includes(MARKER)) return c;

    const releaseCfg = `        release { ${MARKER}
            storeFile file(${q(p.storeFile)})
            storePassword ${q(p.storePassword)}
            keyAlias ${q(p.keyAlias)}
            keyPassword ${q(p.keyPassword)}
        }
`;
    if (!/signingConfigs\s*\{/.test(src)) {
      console.warn('[withReleaseSigning] no signingConfigs block found in build.gradle - skipping.');
      return c;
    }
    src = src.replace(/signingConfigs\s*\{\n/, (m) => m + releaseCfg);
    // Point the release build type at the new config (it uses signingConfigs.debug in the template).
    src = src.replace(/(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/, '$1signingConfig signingConfigs.release');
    if (!src.includes('signingConfig signingConfigs.release')) {
      console.warn('[withReleaseSigning] could not point buildTypes.release at the release signingConfig (template changed?) - release build will be debug-signed.');
    }
    c.modResults.contents = src;
    return c;
  });
};
